/**
 * Dependency-free ledger reducer.
 *
 * A ledger event has the shape:
 *   { id: string, account: string, cents: number, kind: "credit" | "debit" }
 *
 * All arithmetic is done with safe integer Numbers.  Balances that would leave
 * the safe-integer range are rejected instead of producing a rounded result.
 */

export class LedgerError extends Error {
  constructor(message) {
    super(message);
    this.name = "LedgerError";
  }
}

const VALID_KINDS = new Set(["credit", "debit"]);

/**
 * Compare two strings by Unicode code point (not by UTF-16 code unit).
 * JavaScript's default sort compares UTF-16 code units, which orders astral
 * characters differently from their code points.
 */
export function compareCodePoints(a, b) {
  const left = Array.from(a);
  const right = Array.from(b);
  const length = Math.min(left.length, right.length);
  for (let i = 0; i < length; i += 1) {
    const delta = left[i].codePointAt(0) - right[i].codePointAt(0);
    if (delta !== 0) return delta;
  }
  return left.length - right.length;
}

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

function describeLocation(location) {
  return location === undefined ? "" : ` (${location})`;
}

/**
 * Validate one already-JSON-parsed ledger record.
 * Returns a normalized copy containing the four ledger fields.
 */
export function validateEvent(value, location) {
  const where = describeLocation(location);
  if (!isPlainObject(value)) {
    throw new LedgerError(`event${where} must be a JSON object`);
  }

  if (typeof value.id !== "string" || value.id.length === 0) {
    throw new LedgerError(`event${where} has an invalid id: expected a nonempty string`);
  }
  if (typeof value.account !== "string" || value.account.length === 0) {
    throw new LedgerError(`event${where} has an invalid account: expected a nonempty string`);
  }
  if (
    typeof value.cents !== "number" ||
    !Number.isSafeInteger(value.cents) ||
    value.cents < 0
  ) {
    throw new LedgerError(
      `event${where} has invalid cents: expected a nonnegative safe integer`,
    );
  }
  if (typeof value.kind !== "string" || !VALID_KINDS.has(value.kind)) {
    throw new LedgerError(
      `event${where} has an invalid kind: expected "credit" or "debit"`,
    );
  }

  return {
    id: value.id,
    account: value.account,
    cents: value.cents,
    kind: value.kind,
  };
}

function sameEvent(a, b) {
  return (
    a.id === b.id &&
    a.account === b.account &&
    a.cents === b.cents &&
    a.kind === b.kind
  );
}

/**
 * Parse UTF-8 JSONL text into validated records.  Blank/whitespace-only
 * lines are ignored.  No deduplication happens here.
 */
export function parseJsonl(text) {
  if (typeof text !== "string") {
    throw new LedgerError("input must be text");
  }

  // A leading UTF-8 BOM is not part of the first JSON value.
  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);

  const records = [];
  const lines = text.split("\n");
  for (let index = 0; index < lines.length; index += 1) {
    const rawLine = lines[index];
    if (rawLine.trim() === "") continue;

    let parsed;
    try {
      parsed = JSON.parse(rawLine);
    } catch {
      throw new LedgerError(`line ${index + 1} is not valid JSON`);
    }
    records.push(validateEvent(parsed, `on line ${index + 1}`));
  }
  return records;
}

/**
 * Aggregate validated or raw records.
 *
 * Identical records with the same id are counted as duplicate occurrences.
 * Two records with the same id but different ledger fields make the whole
 * input invalid.
 *
 * options.account, when a string, restricts accounts/netCents to that account.
 * uniqueEvents/duplicateEvents always describe the whole input.
 */
export function reduceEvents(records, options = {}) {
  const accountFilter = options.account;
  if (accountFilter !== undefined && accountFilter !== null && typeof accountFilter !== "string") {
    throw new LedgerError("account filter must be a string");
  }

  const byId = new Map();
  const balances = new Map();
  let duplicateEvents = 0;
  let lineHint = 0;

  for (const rawRecord of records) {
    lineHint += 1;
    const event = validateEvent(rawRecord, `record ${lineHint}`);

    const previous = byId.get(event.id);
    if (previous !== undefined) {
      if (!sameEvent(previous, event)) {
        throw new LedgerError(`conflicting records share id ${JSON.stringify(event.id)}`);
      }
      duplicateEvents += 1;
      continue;
    }
    byId.set(event.id, event);

    const delta = event.kind === "credit" ? event.cents : -event.cents;
    const next = (balances.get(event.account) ?? 0) + delta;
    if (!Number.isSafeInteger(next)) {
      throw new LedgerError(
        `balance overflow for account ${JSON.stringify(event.account)}`,
      );
    }
    balances.set(event.account, next);
  }

  const allAccounts = [...balances.keys()].sort(compareCodePoints);
  let selectedAccounts = allAccounts;
  if (typeof accountFilter === "string") {
    selectedAccounts = allAccounts.filter((account) => account === accountFilter);
  }

  const accounts = selectedAccounts.map((account) => ({
    account,
    balanceCents: balances.get(account),
  }));

  let netCents = 0;
  for (const entry of accounts) {
    const next = netCents + entry.balanceCents;
    if (!Number.isSafeInteger(next)) {
      throw new LedgerError("net balance overflow");
    }
    netCents = next;
  }

  return {
    uniqueEvents: byId.size,
    duplicateEvents,
    accounts,
    netCents,
  };
}

/**
 * Main reducer: UTF-8 JSONL text in, summary object out.
 */
export function reduceLedger(text, options = {}) {
  return reduceEvents(parseJsonl(text), options);
}

// Convenient aliases for callers that expect a shorter "reducer" export.
export const reduce = reduceLedger;
export const reducer = reduceLedger;
export default reduceLedger;

#!/usr/bin/env node

import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { TextDecoder } from "node:util";

import { LedgerError, reduceLedger } from "./ledger.mjs";

const USAGE = "usage: node reconcile.mjs INPUT OUTPUT [--account NAME]";

function parseArgs(argv) {
  const positional = [];
  let account = null;

  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];

    if (argument === "--account") {
      if (account !== null) {
        throw new LedgerError("--account may only be specified once");
      }
      if (index + 1 >= argv.length) {
        throw new LedgerError("--account requires a name");
      }
      account = argv[index + 1];
      index += 1;
      if (account.length === 0) {
        throw new LedgerError("--account requires a nonempty name");
      }
    } else if (argument.startsWith("--account=")) {
      if (account !== null) {
        throw new LedgerError("--account may only be specified once");
      }
      account = argument.slice("--account=".length);
      if (account.length === 0) {
        throw new LedgerError("--account requires a nonempty name");
      }
    } else if (argument === "--") {
      for (let rest = index + 1; rest < argv.length; rest += 1) {
        positional.push(argv[rest]);
      }
      break;
    } else if (argument.startsWith("--")) {
      throw new LedgerError(`unknown option ${JSON.stringify(argument)}`);
    } else {
      positional.push(argument);
    }
  }

  if (positional.length !== 2) {
    throw new LedgerError(USAGE);
  }

  return { input: positional[0], output: positional[1], account };
}

function decodeUtf8(buffer) {
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(buffer);
  } catch {
    throw new LedgerError("input is not valid UTF-8");
  }
}

async function writeOutputAtomically(outputPath, contents) {
  const resolved = path.resolve(outputPath);
  const parent = path.dirname(resolved);
  await mkdir(parent, { recursive: true });

  const temporary = path.join(
    parent,
    `.${path.basename(resolved)}.${randomUUID()}.tmp`,
  );

  try {
    await writeFile(temporary, contents, { encoding: "utf8", flag: "wx" });
    await rename(temporary, resolved);
  } catch (error) {
    try {
      await rm(temporary, { force: true });
    } catch {
      // Best-effort cleanup; the original output was never touched.
    }
    throw error;
  }
}

export async function run(argv = process.argv.slice(2)) {
  const { input, output, account } = parseArgs(argv);

  let text;
  try {
    text = decodeUtf8(await readFile(input));
  } catch (error) {
    if (error instanceof LedgerError) throw error;
    throw new LedgerError(`cannot read input ${JSON.stringify(input)}: ${error.message}`);
  }

  const result = reduceLedger(text, account === null ? {} : { account });

  try {
    await writeOutputAtomically(output, `${JSON.stringify(result)}\n`);
  } catch (error) {
    throw new LedgerError(`cannot write output ${JSON.stringify(output)}: ${error.message}`);
  }
}

export async function main(argv = process.argv.slice(2)) {
  try {
    await run(argv);
    return 0;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`reconcile: ${message}\n`);
    return 1;
  }
}

const isDirectInvocation =
  typeof process.argv[1] === "string" &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;

if (isDirectInvocation) {
  const code = await main();
  process.exitCode = code;
}

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtemp, mkdir, readFile, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import { fileURLToPath } from "node:url";

import {
  compareCodePoints,
  LedgerError,
  parseJsonl,
  reduceEvents,
  reduceLedger,
} from "./ledger.mjs";

const CLI = fileURLToPath(new URL("./reconcile.mjs", import.meta.url));

function jsonl(records) {
  return `${records.map((record) => JSON.stringify(record)).join("\n")}\n`;
}

function runCli(args, options = {}) {
  return spawnSync(process.execPath, [CLI, ...args], {
    encoding: "utf8",
    ...options,
  });
}

async function inTempDir(fn) {
  const directory = await mkdtemp(path.join(os.tmpdir(), "ledger-test-"));
  try {
    return await fn(directory);
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}

test("reducer adds credits, subtracts debits, and sorts accounts by code point", () => {
  const text = jsonl([
    { id: "a", account: "alpha", cents: 1000, kind: "credit" },
    { id: "b", account: "alpha", cents: 250, kind: "debit" },
    { id: "c", account: "😀", cents: 7, kind: "credit" },
    { id: "d", account: "A", cents: 3, kind: "credit" },
    { id: "e", account: "é", cents: 11, kind: "credit" },
    { id: "f", account: "\uFFFF", cents: 13, kind: "credit" },
  ]);

  assert.deepEqual(reduceLedger(text), {
    uniqueEvents: 6,
    duplicateEvents: 0,
    accounts: [
      { account: "A", balanceCents: 3 },
      { account: "alpha", balanceCents: 750 },
      { account: "é", balanceCents: 11 },
      { account: "\uFFFF", balanceCents: 13 },
      { account: "😀", balanceCents: 7 },
    ],
    netCents: 784,
  });
});

test("identical duplicate ids are ignored and counted; blanks are ignored", () => {
  const first = { id: "same", account: "a", cents: 42, kind: "credit" };
  const another = { id: "other", account: "a", cents: 8, kind: "debit" };
  const text = `\n${JSON.stringify(first)}\n   \n${JSON.stringify(another)}\n${JSON.stringify(first)}\n${JSON.stringify(first)}\n\n`;

  assert.deepEqual(reduceLedger(text), {
    uniqueEvents: 2,
    duplicateEvents: 2,
    accounts: [{ account: "a", balanceCents: 34 }],
    netCents: 34,
  });
});

test("conflicting records with the same id invalidate the whole input", () => {
  const text = jsonl([
    { id: "dup", account: "a", cents: 10, kind: "credit" },
    { id: "dup", account: "a", cents: 11, kind: "credit" },
  ]);

  assert.throws(() => reduceLedger(text), (error) => {
    assert.ok(error instanceof LedgerError);
    assert.match(error.message, /conflicting records share id/);
    return true;
  });
});

test("integer arithmetic stays exact for large safe integers", () => {
  const text = jsonl([
    { id: "one", account: "big", cents: 2_000_000_000, kind: "credit" },
    { id: "two", account: "big", cents: 1_337_000_001, kind: "credit" },
    { id: "three", account: "big", cents: 999_999_999, kind: "debit" },
  ]);

  const result = reduceLedger(text);
  assert.equal(result.accounts[0].balanceCents, 2_337_000_002);
  assert.equal(result.netCents, 2_337_000_002);
  assert.ok(Number.isSafeInteger(result.netCents));

  assert.throws(
    () =>
      reduceEvents([
        { id: "max", account: "x", cents: Number.MAX_SAFE_INTEGER, kind: "credit" },
        { id: "over", account: "x", cents: 1, kind: "credit" },
      ]),
    /overflow/,
  );
});

test("malformed JSON and invalid fields are rejected", () => {
  assert.throws(() => parseJsonl('{"id":"x",\n'), /not valid JSON/);
  assert.throws(() => parseJsonl("[]\n"), /must be a JSON object/);
  assert.throws(() => parseJsonl("null\n"), /must be a JSON object/);

  const valid = { id: "id", account: "acct", cents: 1, kind: "credit" };
  const invalidRecords = [
    { ...valid, id: "" },
    { ...valid, id: 7 },
    { ...valid, account: "" },
    { ...valid, account: null },
    { ...valid, cents: -1 },
    { ...valid, cents: 1.5 },
    { ...valid, cents: "1" },
    { ...valid, cents: Number.MAX_SAFE_INTEGER + 1 },
    { ...valid, kind: "transfer" },
    { ...valid, kind: null },
  ];

  for (const record of invalidRecords) {
    assert.throws(() => reduceEvents([record]), LedgerError, JSON.stringify(record));
  }

  const missingFields = { id: "missing" };
  assert.throws(() => reduceEvents([missingFields]), /invalid account/);
});

test("--account filtering keeps global event counts and filters netCents", () => {
  const text = jsonl([
    { id: "1", account: "alpha", cents: 100, kind: "credit" },
    { id: "2", account: "beta", cents: 40, kind: "credit" },
    { id: "3", account: "beta", cents: 15, kind: "debit" },
    { id: "2", account: "beta", cents: 40, kind: "credit" },
  ]);

  assert.deepEqual(reduceLedger(text, { account: "beta" }), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: "beta", balanceCents: 25 }],
    netCents: 25,
  });

  assert.deepEqual(reduceLedger(text, { account: "missing" }), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [],
    netCents: 0,
  });
});

test("compareCodePoints orders astral characters after BMP code points", () => {
  const values = ["😀", "\uFFFF", "a", "A", "é"];
  assert.deepEqual(values.sort(compareCodePoints), ["A", "a", "é", "\uFFFF", "😀"]);
});

test("CLI writes the exact summary, creates parent directories, and filters", async () => {
  await inTempDir(async (directory) => {
    const input = path.join(directory, "events.jsonl");
    const output = path.join(directory, "nested", "deep", "汇总 report.json");
    await writeFile(
      input,
      jsonl([
        { id: "1", account: "alpha", cents: 500, kind: "credit" },
        { id: "2", account: "beta", cents: 125, kind: "debit" },
        { id: "1", account: "alpha", cents: 500, kind: "credit" },
      ]),
      "utf8",
    );

    const run = runCli([input, output, "--account", "beta"]);
    assert.equal(run.status, 0, run.stderr);
    assert.equal(run.stdout, "");

    const written = JSON.parse(await readFile(output, "utf8"));
    assert.deepEqual(Object.keys(written), [
      "uniqueEvents",
      "duplicateEvents",
      "accounts",
      "netCents",
    ]);
    assert.deepEqual(written, {
      uniqueEvents: 2,
      duplicateEvents: 1,
      accounts: [{ account: "beta", balanceCents: -125 }],
      netCents: -125,
    });
  });
});

test("CLI leaves an existing output untouched on malformed input", async () => {
  await inTempDir(async (directory) => {
    const input = path.join(directory, "bad.jsonl");
    const output = path.join(directory, "report.json");
    const sentinel = '{"keep":"me"}\n';
    await writeFile(output, sentinel, "utf8");
    await writeFile(input, '{"id":"x","account":"a","cents":1,"kind":"credit"}\nnot json\n', "utf8");

    const run = runCli([input, output]);
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /not valid JSON/);
    assert.equal(await readFile(output, "utf8"), sentinel);
  });
});

test("CLI leaves an existing output untouched on conflicting duplicate ids", async () => {
  await inTempDir(async (directory) => {
    const input = path.join(directory, "conflict.jsonl");
    const output = path.join(directory, "report.json");
    const sentinel = "unchanged";
    await writeFile(output, sentinel, "utf8");
    await writeFile(
      input,
      jsonl([
        { id: "same", account: "a", cents: 1, kind: "credit" },
        { id: "same", account: "a", cents: 2, kind: "credit" },
      ]),
      "utf8",
    );

    const run = runCli([input, output]);
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /conflicting records/);
    assert.equal(await readFile(output, "utf8"), sentinel);
  });
});

test("CLI rejects invalid UTF-8, missing inputs, bad arguments, and bad fields", async () => {
  await inTempDir(async (directory) => {
    const output = path.join(directory, "report.json");
    const sentinel = "preserve";
    await writeFile(output, sentinel, "utf8");

    const invalidUtf8 = path.join(directory, "invalid-utf8.jsonl");
    await writeFile(invalidUtf8, Buffer.from([0xff, 0xfe, 0x7b, 0x7d]));
    let run = runCli([invalidUtf8, output]);
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /valid UTF-8/);
    assert.equal(await readFile(output, "utf8"), sentinel);

    run = runCli([path.join(directory, "absent.jsonl"), output]);
    assert.notEqual(run.status, 0);
    assert.equal(await readFile(output, "utf8"), sentinel);

    const badField = path.join(directory, "bad-field.jsonl");
    await writeFile(
      badField,
      jsonl([{ id: "x", account: "a", cents: -5, kind: "credit" }]),
      "utf8",
    );
    run = runCli([badField, output]);
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /invalid cents/);
    assert.equal(await readFile(output, "utf8"), sentinel);

    run = runCli([badField, output, "--bogus"]);
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /unknown option/);
    assert.equal(await readFile(output, "utf8"), sentinel);

    run = runCli([badField]);
    assert.notEqual(run.status, 0);
    assert.match(run.stderr, /usage:/);
    assert.equal(await readFile(output, "utf8"), sentinel);
  });
});

test("empty input yields an empty but well-formed summary", () => {
  assert.deepEqual(reduceLedger("\n \n\t\n"), {
    uniqueEvents: 0,
    duplicateEvents: 0,
    accounts: [],
    netCents: 0,
  });
});

test("CLI replaces a previous output after a successful run", async () => {
  await inTempDir(async (directory) => {
    const input = path.join(directory, "events.jsonl");
    const output = path.join(directory, "report.json");
    await mkdir(path.dirname(output), { recursive: true });
    await writeFile(output, "old data", "utf8");
    await writeFile(
      input,
      jsonl([{ id: "1", account: "a", cents: 9, kind: "credit" }]),
      "utf8",
    );

    const run = runCli([input, output]);
    assert.equal(run.status, 0, run.stderr);
    const parsed = JSON.parse(await readFile(output, "utf8"));
    assert.equal(parsed.uniqueEvents, 1);
    assert.equal(parsed.accounts[0].balanceCents, 9);
  });
});

